function result = auditQualityAwareMechanismDiagnostic20(root,varargin)
%AUDITQUALITYAWAREMECHANISMDIAGNOSTIC20 Manual paired mechanism diagnostic.
addpath(fullfile(root,'src'));addpath(fullfile(root,'audit_three_layer_helpers'));addpath(fullfile(root,'audit_three_layer_helpers','quality_aware_proposed'));addpath(fullfile(root,'audit_three_layer_helpers','ojcd_baseline'));
parser=inputParser;parser.addParameter('dryRun',false,@(x)islogical(x)&&isscalar(x));parser.addParameter('outputDirectory','',@(x)ischar(x)||(isstring(x)&&isscalar(x)));parser.parse(varargin{:});options=parser.Results;cfg=auditQualityAwareMechanismConfig(root);
if options.dryRun,out=[tempname '_quality_aware_mechanism_dryrun'];elseif strlength(string(options.outputDirectory))>0,out=char(options.outputDirectory);else,out=cfg.mechanismOutput;end
preflight=auditQualityAwareMechanismPreflight(root,cfg,out);schema=auditQualityAwareMechanismSchema();methods=cfg.mechanismMethods;
containers=cell(numel(methods),1);for index=1:numel(methods),containers{index}=struct('method',methods(index),'ownerId',index);end
if options.dryRun
    mkdir(out);cleanup=onCleanup(@()localCleanup(out));tables=localDryTables(schema);result=struct('dryRun',true,'randomPhysicalPacketCount',0,'methodCount',numel(methods),'methods',methods,'schema',schema,'tables',tables,'outputDirectory',out,'stateContainers',{containers},'preflight',preflight);return;
end
if ~exist(out,'dir'),mkdir(out);end;rng(cfg.mechanismMasterSeed,'twister');physicalCount=40;methodCount=numel(methods);packetCells=cell(physicalCount*methodCount,1);hashCells=cell(physicalCount*methodCount,1);rdaCells=cell(physicalCount*methodCount,1);runtimeCells=cell(physicalCount*methodCount,1);rejectionCells=cell(physicalCount*methodCount*3,1);rowCursor=0;rejectCursor=0;physicalCursor=0;maximumFrozenHashAbsoluteDifference=0;nonExactFrozenHashFieldCount=0;toleranceMatchedFrozenHashFieldCount=0;wall=tic;
for conditionIndex=1:numel(cfg.Ncodeword)
    nCodeword=cfg.Ncodeword(conditionIndex);conditionSeed=cfg.mechanismMasterSeed+100000*nCodeword;
    for packetIndex=1:cfg.mechanismPacketCountPerCondition
        packetSeed=conditionSeed+packetIndex;rng(packetSeed,'twister');packet=auditQualityAwareMiniPacket(cfg,nCodeword);physicalCursor=physicalCursor+1;
        hashAudit=auditVerifyFrozenPacketHashes(packet,packetIndex,conditionSeed,packetSeed,preflight.frozenPairingTable,cfg.frozenHashAbsoluteTolerance);
        maximumFrozenHashAbsoluteDifference=max(maximumFrozenHashAbsoluteDifference,hashAudit.maximumAbsoluteDifference);nonExactFrozenHashFieldCount=nonExactFrozenHashFieldCount+hashAudit.absoluteToleranceMatchCount;toleranceMatchedFrozenHashFieldCount=toleranceMatchedFrozenHashFieldCount+hashAudit.absoluteToleranceMatchCount;
        executionIndices=circshift(1:methodCount,[0 mod(packetIndex-1,methodCount)]);executionPosition=zeros(1,methodCount);executionPosition(executionIndices)=1:methodCount;
        onlinePacket=struct('pilotObservation',packet.obs,'receivedData',packet.y, ...
            'validDataMask',packet.validReMask,'validReMask',packet.validReMask, ...
            'noiseVar',cfg.noiseVar,'rho',cfg.rho,'Npayload',packet.Npayload, ...
            'nCodeword',packet.nCodeword,'usefulBitMask',packet.usefulBitMask);
        for orderPosition=1:methodCount
            methodIndex=executionIndices(orderPosition);method=methods(methodIndex);
            try
                estimate=auditMechanismRunSingleEstimator(cfg,onlinePacket,method);receiver=auditMechanismOnlineReceive(cfg,onlinePacket,estimate.Hhat,estimate.onlineEstimationRuntimeSeconds);
                offline=auditMechanismOfflineDetectionMetrics(cfg,receiver,estimate.Hhat,packet.H,packet.qam,packet.codedBits,packet.validReMask);
            catch exception
                error('Mechanism diagnostic failed: payloadSymbols=%d packetIndex=%d method=%s symbolIndex=NaN targetSubcarrier=NaN candidateRadius=NaN. %s',packet.Npayload,packetIndex,method,exception.message);
            end
            row=localPacketRow(packet,packetIndex,method,executionPosition(methodIndex),conditionSeed,packetSeed,receiver,offline,estimate);rowCursor=rowCursor+1;packetCells{rowCursor}=struct2table(row,'AsArray',true);hashCells{rowCursor}=localHashRow(packet,packetIndex,method,conditionSeed,packetSeed);rdaCells{rowCursor}=localRdaRow(packet.Npayload,packetIndex,method,estimate.audit);runtimeCells{rowCursor}=table(packet.Npayload,packetIndex,method,executionPosition(methodIndex),row.onlineRuntimeSeconds,row.offlineAuditRuntimeSeconds,row.totalMethodRuntimeSeconds,'VariableNames',schema.runtime);
            rejection=localRejectionRows(packet.Npayload,method,estimate.audit);for rr=1:height(rejection),rejectCursor=rejectCursor+1;rejectionCells{rejectCursor}=rejection(rr,:);end
        end
    end
end
packetTable=vertcat(packetCells{:});packetTable=packetTable(:,schema.packet);pairingTable=vertcat(hashCells{:});rdaTable=vertcat(rdaCells{:});runtimeTable=vertcat(runtimeCells{:});rejectionRaw=vertcat(rejectionCells{1:rejectCursor});rejectionTable=auditAggregateMechanismRejections(rejectionRaw,schema);localAssertPairing(pairingTable,methodCount);
alignmentTable=packetTable(:,schema.alignment);summaryTable=localSummary(packetTable);pairedTable=auditBuildMechanismPairedStatistics(packetTable,schema);correlationTable=localCorrelations(packetTable);
writetable(packetTable,fullfile(out,'quality_aware_mechanism_packet_level.csv'));writetable(summaryTable,fullfile(out,'quality_aware_mechanism_summary.csv'));writetable(pairedTable,fullfile(out,'quality_aware_mechanism_paired_statistics.csv'));writetable(pairingTable,fullfile(out,'quality_aware_mechanism_pairing_hashes.csv'));writetable(rdaTable,fullfile(out,'quality_aware_mechanism_rda_audit.csv'));writetable(rejectionTable,fullfile(out,'quality_aware_mechanism_rejection_audit.csv'));writetable(alignmentTable,fullfile(out,'quality_aware_mechanism_detection_alignment_packet_level.csv'));writetable(correlationTable,fullfile(out,'quality_aware_mechanism_detection_alignment_correlation.csv'));writetable(runtimeTable,fullfile(out,'quality_aware_mechanism_runtime_audit.csv'));
    wallTime=toc(wall);preflight.maximumFrozenHashAbsoluteDifference=maximumFrozenHashAbsoluteDifference;preflight.nonExactFrozenHashFieldCount=nonExactFrozenHashFieldCount;preflight.toleranceMatchedFrozenHashFieldCount=toleranceMatchedFrozenHashFieldCount;localReport(out,cfg,packetTable,wallTime,preflight);result=struct('dryRun',false,'randomPhysicalPacketCount',physicalCursor,'packetTable',packetTable,'summaryTable',summaryTable,'pairedTable',pairedTable,'pairingTable',pairingTable,'rdaTable',rdaTable,'rejectionTable',rejectionTable,'alignmentTable',alignmentTable,'correlationTable',correlationTable,'runtimeTable',runtimeTable,'frozenHashAudit',preflight,'outputDirectory',out);
end

function tables=localDryTables(schema),names=fieldnames(schema);tables=struct();for i=1:numel(names),tables.(names{i})=cell2table(cell(0,numel(schema.(names{i}))),'VariableNames',schema.(names{i}));end,end
function row=localPacketRow(packet,packetIndex,method,executionOrder,conditionSeed,packetSeed,receiver,offline,estimate)
    row=offline;row.payloadSymbols=packet.Npayload;row.nCodeword=packet.nCodeword;row.packetIndex=packetIndex;row.method=method;row.executionOrder=executionOrder;row.conditionSeed=conditionSeed;row.packetSeed=packetSeed;row.onlineRuntimeSeconds=receiver.onlineRuntimeSeconds;row.offlineAuditRuntimeSeconds=offline.offlineAuditRuntimeSeconds;row.totalMethodRuntimeSeconds=row.onlineRuntimeSeconds+row.offlineAuditRuntimeSeconds;row.hasNaN=receiver.hasNaN;row.hasInf=receiver.hasInf;row.futureSymbolReadCount=estimate.futureSymbolReadCount;row.testTruthOnlineUseCount=estimate.testTruthOnlineUseCount;row.solverFailureCount=localApplicable(method,estimate.audit.solverFailureCount);row.covarianceNonPsdCount=localApplicable(method,estimate.audit.covarianceRejectedCount);a=estimate.audit;row.candidateFeasibleCount=localApplicable(method,a.candidateFeasibleCount);row.daUpdateCount=localApplicable(method,a.daUpdateCount);row.noCandidateCount=localApplicable(method,a.noCandidateCount);row.innovationRejectCount=localApplicable(method,a.innovationHardRejectedCount);row.innovationRejectRate=localApplicable(method,a.innovationHardRejectedCount/max(a.candidateFeasibleCount,1));row.meanRdaTrace=localStat(a.rdaTrace,'mean');row.medianRdaTrace=localStat(a.rdaTrace,'median');row.p95RdaTrace=auditDeterministicPercentile(a.rdaTrace,.95);row.meanNormalizedNis=localStat(a.nis/8,'mean');row.medianNormalizedNis=localStat(a.nis/8,'median');row.p95NormalizedNis=auditDeterministicPercentile(a.nis/8,.95);row.meanNisInflation=localStat(a.nisInflation,'mean');row.p95NisInflation=auditDeterministicPercentile(a.nisInflation,.95);row.meanDecisionInflation=localStat(a.decisionInflation,'mean');row.p95DecisionInflation=auditDeterministicPercentile(a.decisionInflation,.95);row=localAttachHashes(row,packet.hashes);
end
function value=localApplicable(method,value),if method=="BaseKalmanCausal_EP",value=NaN;end,end
function row=localAttachHashes(row,h),names=fieldnames(h);for i=1:numel(names),row.(names{i})=h.(names{i});end,end
function T=localHashRow(packet,packetIndex,method,conditionSeed,packetSeed),h=packet.hashes;s=auditQualityAwareMechanismSchema();T=table(packet.Npayload,packet.nCodeword,packetIndex,method,conditionSeed,packetSeed,h.informationBitsHash,h.transmitBitsHash,h.codedBitsHash,h.qamSymbolsHash,h.paddingMaskHash,h.channelHash,h.noiseHash,h.receivedSignalHash,h.pilotObservationHash,'VariableNames',s.hash);end
function T=localRdaRow(payload,packet,method,a),T=table(payload,packet,method,localApplicable(method,a.candidateFeasibleCount),localApplicable(method,a.daUpdateCount),localApplicable(method,a.innovationHardRejectedCount),localApplicable(method,a.innovationHardRejectedCount/max(a.candidateFeasibleCount,1)),localStat(a.rdaTrace,'mean'),localStat(a.rdaTrace,'median'),auditDeterministicPercentile(a.rdaTrace,.95),localStat(a.rdaTrace,'min'),localStat(a.rdaTrace,'max'),localStat(a.nis/8,'mean'),localStat(a.nis/8,'median'),auditDeterministicPercentile(a.nis/8,.95),localStat(a.nisInflation,'mean'),auditDeterministicPercentile(a.nisInflation,.95),localStat(a.decisionInflation,'mean'),auditDeterministicPercentile(a.decisionInflation,.95),'VariableNames',auditQualityAwareMechanismSchema().rda);end
function T=localRejectionRows(payload,method,a)
if method=="BaseKalmanCausal_EP",T=table(payload,method,NaN,NaN,NaN,NaN,NaN,NaN,NaN,NaN,NaN,NaN,NaN,'VariableNames',auditQualityAwareMechanismSchema().rejection);return;end
if method=="QualityWindowOnlyCausal_EP"||method=="QualityAwareLocalDAKalmanCausal_EP",radii=1:3;else,radii=3;end
T=cell(numel(radii),1);for index=1:numel(radii),radius=radii(index);T{index}=table(payload,method,radius,a.insufficientSampleCountByRadius(radius),a.llrGateRejectedCountByRadius(radius),a.gramRankRejectedCountByRadius(radius),a.gramRcondRejectedCountByRadius(radius),a.nonfiniteCandidateCountByRadius(radius),a.innovationHardRejectedCountByRadius(radius),a.covarianceRejectedCountByRadius(radius),a.solverFailureCountByRadius(radius),a.acceptedCandidateCountByRadius(radius),a.noCandidateCount,'VariableNames',auditQualityAwareMechanismSchema().rejection);end;T=vertcat(T{:});
end
function localAssertPairing(T,count),keys=unique(T(:,{'payloadSymbols','packetIndex'}),'rows');names=auditQualityAwareMechanismSchema().hash(7:end);for i=1:height(keys),rows=T(T.payloadSymbols==keys.payloadSymbols(i)&T.packetIndex==keys.packetIndex(i),:);assert(height(rows)==count);for j=1:numel(names),v=rows.(names{j});assert(all(v==v(1)));end,end,end
function T=localSummary(R),keys=unique(R(:,{'payloadSymbols','method'}),'rows');cells=cell(height(keys),1);for i=1:height(keys),p=R(R.payloadSymbols==keys.payloadSymbols(i)&R.method==keys.method(i),:);cells{i}=table(keys.payloadSymbols(i),keys.method(i),height(p),mean(p.csiNmse),median(p.csiNmse),mean(p.preLdpcBer),median(p.preLdpcBer),mean(p.codewordPassRate),mean(p.payloadGoodputMbps),mean(p.onlineRuntimeSeconds),median(p.onlineRuntimeSeconds),nnz(p.hasNaN),nnz(p.hasInf),'VariableNames',auditQualityAwareMechanismSchema().summary);end;T=vertcat(cells{:});end
function T=localCorrelations(R)
metricPairs=["csiNmse","preLdpcBer";"worstStreamCsiNmse","preLdpcBer";"p95ReNormalizedError","preLdpcBer";"p99ReNormalizedError","preLdpcBer";"deepFadeCsiNmse","preLdpcBer";"softEvmRms","preLdpcBer";"worstStreamSoftEvmRms","preLdpcBer";"softEvmRms","codewordPassRate";"deepFadeCsiNmse","codewordPassRate"];
methods=unique(R.method);methods(methods=="FixedRadius3Causal_EP")=[];cells=cell(2*numel(methods)*size(metricPairs,1),1);cursor=0;for payload=unique(R.payloadSymbols).',base=sortrows(R(R.payloadSymbols==payload&R.method=="FixedRadius3Causal_EP",:),'packetIndex');for method=methods.',part=sortrows(R(R.payloadSymbols==payload&R.method==method,:),'packetIndex');for p=1:size(metricPairs,1),x=part.(metricPairs(p,1))-base.(metricPairs(p,1));y=part.(metricPairs(p,2))-base.(metricPairs(p,2));mask=isfinite(x)&isfinite(y);cursor=cursor+1;cells{cursor}=table(payload,method,metricPairs(p,1),metricPairs(p,2),nnz(mask),auditPearsonCorrelation(x,y),auditSpearmanCorrelation(x,y),'VariableNames',auditQualityAwareMechanismSchema().correlation);end,end,end;T=vertcat(cells{1:cursor});end
function localReport(out,cfg,R,wall,preflight)
file=fopen(fullfile(out,'quality_aware_mechanism_run_report.txt'),'w','n','UTF-8');assert(file>=0);cleanup=onCleanup(@()fclose(file));
fprintf(file,'Quality-aware mechanism diagnostic20 (diagnostic evidence only)\n');
fprintf(file,'seed=%d; packetsPerCondition=%d; payloadSymbols=[%s]; methodCount=%d; rows=%d; measuredWallTimeSeconds=%.9g\n',cfg.mechanismMasterSeed,cfg.mechanismPacketCountPerCondition,strjoin(string(cfg.Npayload),','),numel(cfg.mechanismMethods),height(R),wall);
fprintf(file,'Frozen parameters: fixedRadius=3, LLR threshold=%.9g, min samples=%d, Gram rcond threshold=%.9g, NIS dimension=%d, hard threshold=%.9g, eigen floors=[%.9g %.9g].\n',cfg.llrThreshold,cfg.minEffectiveSamples,cfg.gramRcondThreshold,cfg.stateDimension,cfg.chiSquareHardThresholdDof8P999,cfg.absoluteEigenFloor,cfg.relativeEigenFloor);
fprintf(file,'Methods: %s\n',strjoin(cfg.mechanismMethods,', '));
fprintf(file,'A FixedRadius3: RDA=Rlegacy; no NIS. B: A plus hard reject NIS>26.1245. C: B plus alphaNis=max(1,NIS/8). D: RDA=Rls only; no NIS. E: D plus hard reject. F: E plus alphaNis. G: fixed radius 3 with Rdec=alphaDec*Rls and RDA=alphaNis*Rdec. Final: same adaptive formula with online selection over radii [1 2 3].\n');
fprintf(file,'For every NIS branch: nu=zDA-hPilot, S=PPilot+Rbase, NIS=real(nu''*(S\\nu)); no inv is used. Each target has one frozen pilot posterior and at most one DA update.\n');
fprintf(file,'Online runtime includes causal pilot estimation, EP decisions, local LS/quality/NIS/fusion and receiver EP/LDPC. Offline audit runtime includes H_true/QAM-based NMSE, RE tails, deep-fade metrics and EVM only. Hashing, CSV, summaries and correlations are excluded.\n');
fprintf(file,'Offline metrics: stream NMSE is error energy/truth energy per transmit stream; RE normalized error is ||Hhat-Htrue||_F^2/max(||Htrue||_F^2,eps); deep fade is the common packet bottom-10%% true gain mask; soft/hard EVM is RMS symbol error normalized by true-symbol energy; EVM-effective SINR is 10log10(true energy/soft-error energy).\n');
fprintf(file,'Pearson uses centered dot products. Spearman uses deterministic average tied ranks followed by Pearson; fewer than 3 finite pairs or a constant vector returns NaN.\n');
fprintf(file,'Pairing gate: frozen rows=%d, schemaPass=%d, protectedHashesPass=%d; NaN gates=%d, Inf gates=%d, futureSymbolReadCount=%g, testTruthOnlineUseCount=%g.\n',height(preflight.frozenPairingTable),preflight.frozenPairingSchemaPass,preflight.protectedHashesPass,nnz(R.hasNaN),nnz(R.hasInf),sum(R.futureSymbolReadCount),sum(R.testTruthOnlineUseCount));
fprintf(file,'Frozen hash comparison: seeds use exact integer equality; hashes use exact equality first, then fixed absolute tolerance %.17g for CSV decimal quantization only. maximumAbsoluteDifference=%.17g; nonExactFields=%d; toleranceMatchedFields=%d. No relative tolerance is used.\n',cfg.frozenHashAbsoluteTolerance,preflight.maximumFrozenHashAbsoluteDifference,preflight.nonExactFrozenHashFieldCount,preflight.toleranceMatchedFrozenHashFieldCount);
fprintf(file,'Rejection audit categories: insufficient samples, LLR gate, rank, Gram rcond, nonfinite candidate, innovation hard reject, covariance reject, solver failure, accepted candidate and no-candidate target.\n');
comparisons=["FixedRadius3LegacyHardRejectCausal_EP","FixedRadius3Causal_EP","B-A hard rejection";"FixedRadius3LegacyNisInflationCausal_EP","FixedRadius3LegacyHardRejectCausal_EP","C-B NIS inflation";"FixedRadius3LsCovOnlyCausal_EP","FixedRadius3Causal_EP","D-A RLS covariance";"FixedRadius3LsCovHardRejectCausal_EP","FixedRadius3LsCovOnlyCausal_EP","E-D hard rejection";"FixedRadius3LsCovNisInflationCausal_EP","FixedRadius3LsCovHardRejectCausal_EP","F-E NIS inflation";"FixedRadius3FullAdaptiveRdaCausal_EP","FixedRadius3LsCovNisInflationCausal_EP","G-F decision inflation";"QualityAwareLocalDAKalmanCausal_EP","FixedRadius3FullAdaptiveRdaCausal_EP","Final-G dynamic window";"QualityWindowOnlyCausal_EP","FixedRadius3Causal_EP","quality window-old RDA vs A"];
for payload=unique(R.payloadSymbols).'
    fprintf(file,'payloadSymbols=%d paired mean deltas (first method minus second):\n',payload);
    for index=1:size(comparisons,1)
        delta=localReportDelta(R,payload,comparisons(index,1),comparisons(index,2));
        fprintf(file,'  %s: CSI_NMSE=%+.9g, preLDPC_BER=%+.9g, codewordPassRate=%+.9g, softEVM=%+.9g, onlineRuntimeSeconds=%+.9g\n',comparisons(index,3),delta(1),delta(2),delta(3),delta(4),delta(5));
    end
end
fprintf(file,'Interpretation must remain diagnostic: 20 packets can show mechanism trends but do not establish formal statistical significance.\n');
end
function delta=localReportDelta(R,payload,methodA,methodB)
a=sortrows(R(R.payloadSymbols==payload&R.method==methodA,:),'packetIndex');b=sortrows(R(R.payloadSymbols==payload&R.method==methodB,:),'packetIndex');assert(height(a)==height(b)&&all(a.packetIndex==b.packetIndex));
names={'csiNmse','preLdpcBer','codewordPassRate','softEvmRms','onlineRuntimeSeconds'};delta=zeros(1,numel(names));for index=1:numel(names),delta(index)=mean(a.(names{index})-b.(names{index}));end
end
function value=localStat(data,kind),data=data(isfinite(data));if isempty(data),value=NaN;else,value=feval(kind,data);end,end
function localCleanup(path),if exist(path,'dir'),rmdir(path,'s');end,end
